target.css:
:root {
  --ink: #202b3a;
  --muted: #677487;
  --paper: #fffdf8;
  --line: #dce3e7;
  --navy: #183b5b;
  --blue: #2776a8;
  --mist: #edf5f8;
  --gold: #d99b35;
  --gold-pale: #fff2d8;
  --white: #ffffff;
}

* {
  box-sizing: border-box;
}

.rehearsal-card {
  width: 480px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: var(--paper);
  color: var(--ink);
}

.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 16px 12px;
  border-bottom: 1px solid var(--line);
}

.title-lockup {
  min-width: 0;
}

.eyebrow {
  margin: 0 0 3px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.card-header h1 {
  margin: 0;
  color: var(--navy);
  font-size: 21px;
  line-height: 1.1;
}

.status-chip {
  flex: 0 0 auto;
  margin-left: 12px;
  padding: 5px 8px;
  border-radius: 999px;
  background: var(--gold-pale);
  color: var(--gold);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.05em;
}

.content-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 148px;
  gap: 14px;
  padding: 13px 16px;
}

.schedule-heading {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 5px;
}

.schedule-heading h2,
.summary h2 {
  margin: 0;
  color: var(--navy);
  font-size: 13px;
  font-weight: 800;
}

.schedule-heading span {
  color: var(--muted);
  font-size: 11px;
}

.schedule-list {
  display: grid;
  gap: 1px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.schedule-item {
  display: grid;
  grid-template-columns: 40px 9px minmax(0, 1fr);
  align-items: center;
  column-gap: 8px;
  padding: 6px 7px;
  border-radius: 8px;
}

.schedule-item.active {
  background: var(--mist);
}

.time {
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
}

.cue-dot {
  width: 8px;
  height: 8px;
  border: 2px solid var(--line);
  border-radius: 50%;
  background: var(--white);
}

.active .cue-dot {
  border-color: var(--blue);
  background: var(--blue);
}

.item-copy {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 1px;
}

.item-copy strong {
  overflow: hidden;
  color: var(--ink);
  font-size: 12px;
  line-height: 1.15;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.item-copy span {
  color: var(--muted);
  font-size: 11px;
}

.summary {
  padding: 10px 11px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--white);
}

.score {
  display: flex;
  align-items: end;
  justify-content: space-between;
  margin: 8px 0 7px;
}

.score span,
.stat span {
  color: var(--muted);
  font-size: 10px;
}

.score strong {
  color: var(--blue);
  font-size: 25px;
  line-height: 0.85;
}

.stats {
  border-top: 1px solid var(--line);
}

.stat {
  display: flex;
  justify-content: space-between;
  margin: 0;
  padding: 6px 0 0;
}

.stat + .stat {
  padding-top: 4px;
}

.stat strong {
  color: var(--ink);
  font-size: 10px;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 10px 16px;
  border-top: 1px solid var(--line);
  background: var(--mist);
}

.legend {
  display: flex;
  align-items: center;
  gap: 5px;
  margin: 0;
  color: var(--muted);
  font-size: 10px;
}

.legend i {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--blue);
}

.actions {
  display: flex;
  gap: 6px;
}

.actions button {
  padding: 7px 9px;
  border-radius: 7px;
  font-size: 11px;
  font-weight: 800;
}

.secondary {
  border: 1px solid var(--line);
  background: var(--white);
  color: var(--navy);
}

.primary {
  border: 1px solid var(--navy);
  background: var(--navy);
  color: var(--white);
}

